    formulaLabels: ['门店放行率', '首次验收通过率'], formulae: ['所有强制关口均关闭的门店数 ÷ 本批计划门店数 × 100%', '无需重洗即验收通过的代表性负载数 ÷ 代表性测试负载数 × 100%'],
